// Credits (quality lane; docs/QUALITY-PLAN.md Phase D item 15): opened from the ☰ menu ("Credits"), drawn in the
// same sheet, "Back" returns to the menu.
//
// Plain words (docs/UX-SIMPLE.md): who made the game, then "Made with" — each shipped third-party part on one line
// (name, what it is, licence) with its full licence text behind a closed "Licence" toggle — then the people whose
// tricks we learned from (no pictures, sounds or code were copied). The third-party list is generated by
// scripts/third-party.mjs into public/licenses/third-party.json (also THIRD-PARTY-NOTICES.md) and fetched here;
// where it cannot be fetched (the single-file build ships no public/ files) the short built-in list below is shown.
import { $, $$, esc } from '../util';
import type { PanelHost } from './common';

export interface CreditComponent {
  id: string;
  name: string;
  role: string;
  version?: string;
  license: string;
  copyright?: string;
  url?: string;
  file?: string;
  text?: string;
}

export interface CreditTechnique {
  source: string;
  licence: string;
  use: string;
}

export interface CreditsData {
  components: CreditComponent[];
  techniques: CreditTechnique[];
}

/** Where the generated notices are served (relative to the page: public/licenses/third-party.json). */
export const NOTICES_URL = 'licenses/third-party.json';

/** Built-in summary for builds without public/ (kept in step with the generated JSON by tests/quality-credits). */
export const FALLBACK_CREDITS: CreditsData = {
  components: [
    { id: 'phaser', name: 'Phaser', role: 'Game engine', license: 'MIT', copyright: 'Copyright (c) 2024 Richard Davey, Phaser Studio Inc.' },
    { id: 'eventemitter3', name: 'eventemitter3', role: 'Event library inside Phaser', license: 'MIT', copyright: 'Copyright (c) 2014 Arnout Kazemier' },
    { id: '@fontsource/pixelify-sans', name: 'Pixelify Sans', role: 'Pixel font for menus and titles', license: 'OFL-1.1', copyright: 'Copyright 2021 The Pixelify Sans Project Authors (https://github.com/eifetx/Pixelify-Sans)' },
    { id: '@fontsource/tiny5', name: 'Tiny5', role: 'Pixel font for small numbers', license: 'OFL-1.1', copyright: 'Copyright 2022-2024 The Tiny5 Project Authors (https://github.com/Gissio/font_tiny5)' },
    { id: 'zzfx', name: 'ZzFX', role: 'Sound maker (every sound is built from it in code)', license: 'MIT', copyright: 'Copyright (c) 2019 Frank Force' },
    { id: 'vite', name: 'Vite', role: 'Build tool (its small page-loading helper ships with the game)', license: 'MIT', copyright: 'Copyright (c) 2019-present, VoidZero Inc. and Vite contributors' },
  ],
  techniques: [
    { source: 'Sprite Fusion pixel-art VFX, © Hugo Duprez', licence: 'MIT', use: '' },
    { source: 'patch-gg/pixelfx, © Patch', licence: 'MIT', use: '' },
    { source: 'Pixel ability-fx forge (GameDev-Toolkit)', licence: 'Apache-2.0', use: '' },
    { source: 'Pedro Medeiros (Saint11) pixel-art tutorials', licence: 'CC BY 4.0', use: '' },
    { source: 'B. E. Bayer (1973), ordered dithering', licence: 'public algorithm', use: '' },
    { source: 'Squirrel Eiserloh, "Juicing Your Cameras With Math" (GDC 2016)', licence: 'talk', use: '' },
    { source: 'Midpoint-displacement lightning; CIEDE2000 (Sharma 2005); Machado 2009 CVD', licence: 'public algorithms', use: '' },
  ],
};

/** Licence ids in plain words. */
export function licenceName(id: string): string {
  const k = id.trim();
  if (k === 'MIT') return 'MIT licence';
  if (k === 'OFL-1.1') return 'SIL Open Font License 1.1';
  if (k === 'Apache-2.0') return 'Apache licence 2.0';
  if (k === 'CC BY 4.0') return 'Creative Commons BY 4.0';
  return k;
}

/** One technique source on one line: drop the URL in brackets and the year-led copyright noise. */
function sourceLine(t: CreditTechnique): string {
  return t.source.replace(/\s*\((?:[a-z0-9.-]+\.[a-z]{2,}[^)]*|derivative of the above)\)/gi, '').replace(/\s+/g, ' ').trim();
}

/**
 * A licence text for a phone-width box: the files wrap at ~80 columns, so the lines of each paragraph are joined
 * (the box wraps them) and rule lines of dashes are dropped. The wording is unchanged.
 */
export function reflowLicence(text: string): string {
  return text
    .replace(/\r\n/g, '\n')
    .split(/\n\s*\n/)
    .map((para) =>
      para
        .split('\n')
        .map((l) => l.trim())
        .filter((l) => l && !/^[-=_*]{3,}$/.test(l))
        .join(' '),
    )
    .filter(Boolean)
    .join('\n\n');
}

function componentHtml(c: CreditComponent): string {
  const text = c.text ? `${c.copyright ? `<p class="cr-copy">${esc(c.copyright)}</p>` : ''}<pre class="cr-text">${esc(reflowLicence(c.text))}</pre>` : '';
  return `<li class="cr-item">
    <div class="cr-line"><b>${esc(c.name)}</b><span>${esc(c.role)}</span></div>
    <div class="cr-lic">${esc(licenceName(c.license))}${!text && c.copyright ? ` · ${esc(c.copyright)}` : ''}</div>
    ${text ? `<button class="cr-more hint-t" aria-expanded="false">Licence</button><div class="cr-box hidden">${text}</div>` : ''}
  </li>`;
}

/** The Credits sheet body. */
export function creditsHtml(data: CreditsData): string {
  const made = data.components.map(componentHtml).join('');
  const tricks = data.techniques.map((t) => `<li>${esc(sourceLine(t))} <small>${esc(licenceName(t.licence))}</small></li>`).join('');
  return `<div class="cr-game">
      <b>Omnipath</b>
      <p>An original game: every picture and every sound is made by its own code.</p>
    </div>
    <h3 class="cr-h">Made with</h3>
    <ul class="cr-list">${made}</ul>
    <h3 class="cr-h">Tricks learned from</h3>
    <p class="cr-note">No pictures, sounds or code were copied.</p>
    <ul class="cr-tricks">${tricks}</ul>
    <div class="mn-actions cr-actions"><button class="btn big gold cr-back">Back</button></div>`;
}

let cached: Promise<CreditsData | null> | null = null;

/** The generated notices (null when they cannot be fetched: the built-in list is used). Fetched once. */
export function loadCredits(fetcher: typeof fetch | undefined = typeof fetch === 'function' ? fetch : undefined): Promise<CreditsData | null> {
  if (cached) return cached;
  if (!fetcher) return Promise.resolve(null);
  cached = fetcher(NOTICES_URL)
    .then((r) => (r.ok ? r.json() : null))
    .then((d: unknown) => {
      const ok = !!d && typeof d === 'object' && Array.isArray((d as CreditsData).components) && Array.isArray((d as CreditsData).techniques);
      return ok ? (d as CreditsData) : null;
    })
    .catch(() => null);
  void cached.then((d) => {
    if (!d) cached = null; // try again next time (offline now, online later)
  });
  return cached;
}

const CSS_ID = 'omnipath-credits-css';
const CSS = `
.sheet.credits-sheet .cr-game { display: flex; flex-direction: column; gap: 2px; margin-bottom: 6px; }
.sheet.credits-sheet .cr-game b { font-size: 22px; color: #ffe6a0; }
.sheet.credits-sheet .cr-game p, .sheet.credits-sheet .cr-note { margin: 0; color: #b9a98a; font-size: 14px; }
.sheet.credits-sheet .cr-h { margin: 14px 0 6px; font-size: 16px; color: #e9c46a; border-top: 1px solid rgba(233, 196, 106, 0.18); padding-top: 10px; }
.sheet.credits-sheet .cr-list, .sheet.credits-sheet .cr-tricks { list-style: none; margin: 0; padding: 0; }
.sheet.credits-sheet .cr-item { padding: 6px 0; }
.sheet.credits-sheet .cr-item + .cr-item { border-top: 1px dashed rgba(233, 196, 106, 0.12); }
.sheet.credits-sheet .cr-line { display: flex; flex-wrap: wrap; align-items: baseline; gap: 4px 10px; color: #f2e6c8; font-size: 16px; }
.sheet.credits-sheet .cr-line b { color: #ffe6a0; }
.sheet.credits-sheet .cr-line span { color: #f2e6c8; font-size: 14px; }
.sheet.credits-sheet .cr-lic { color: #b9a98a; font-size: 13px; margin-top: 2px; overflow-wrap: anywhere; }
.sheet.credits-sheet .cr-more { margin-top: 4px; }
.sheet.credits-sheet .cr-box { margin-top: 6px; }
.sheet.credits-sheet .cr-copy { margin: 0 0 4px; color: #f2e6c8; font-size: 13px; overflow-wrap: anywhere; }
.sheet.credits-sheet .cr-text { margin: 0; padding: 8px; max-height: 240px; overflow: auto; white-space: pre-wrap; overflow-wrap: anywhere;
  background: #1a130c; border: 2px solid #5b4a32; border-radius: 3px; color: #d8cbb0; font: 12px / 1.35 ui-monospace, Menlo, monospace; }
.sheet.credits-sheet .cr-tricks li { padding: 4px 0; color: #f2e6c8; font-size: 14px; }
.sheet.credits-sheet .cr-tricks small { color: #b9a98a; font-size: 12px; margin-left: 4px; white-space: nowrap; }
.sheet.credits-sheet .cr-actions { display: flex; margin-top: 14px; }
`;

function ensureCss(): void {
  if (typeof document === 'undefined' || document.getElementById(CSS_ID)) return;
  const st = document.createElement('style');
  st.id = CSS_ID;
  st.textContent = CSS;
  document.head.append(st);
}

function wire(body: HTMLElement, back: () => void): void {
  $(body, '.cr-back').addEventListener('click', back);
  $$<HTMLButtonElement>(body, '.cr-more').forEach((b) =>
    b.addEventListener('click', () => {
      const box = b.nextElementSibling as HTMLElement | null;
      if (!box) return;
      const hidden = box.classList.toggle('hidden');
      b.setAttribute('aria-expanded', String(!hidden));
      b.classList.toggle('open', !hidden);
    }),
  );
}

/** Draws the Credits sheet into the menu's modal; `back` redraws the menu. */
export function renderCredits(host: PanelHost, back: () => void): void {
  ensureCss();
  const draw = (data: CreditsData) => {
    const prev = host.modal.querySelector<HTMLElement>('.credits-sheet .sheet-body');
    const scroll = prev?.scrollTop ?? 0;
    const body = host.sheet('Credits', creditsHtml(data), 'hud-sheet credits-sheet');
    body.scrollTop = scroll;
    wire(body, back);
  };
  draw(FALLBACK_CREDITS);
  void loadCredits().then((data) => {
    // Still on the Credits sheet (not closed, not back at the menu): swap in the full list with the licence texts.
    if (data && host.modal.querySelector('.credits-sheet') && !host.modal.classList.contains('hidden')) draw(data);
  });
}
